#!/usr/bin/env python3
# spec: GAME-10 COMP-1 COMP-2 COMP-3 COMP-4 COMP-5
# requires: cmd:bash cmd:sh
# The sway config the Thor actually gets, generated by the real thor-sway-rotate.sh and 111-sway-init's Thor lines in a temp dir,
# with its for_window and assign rules evaluated against each kind of window. Rules are all this sees: that sway keeps focus on the
# game and that each window really opens where the rules say are device and human checks. Also: thor-bottom-idle-off.sh (GAME-10),
# thor-bottom-rotate.sh (COMP-1) and vertical-check's use of the lowerdeck setting (COMP-3), against a fake swaymsg.
import os
import re
import stat
import subprocess
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
PACKAGES = f"{HERE}/../.."


def rewrite(text, paths):
    return re.sub("|".join(map(re.escape, paths)), lambda m: paths[m.group(0)], text)


def executable(path, text):
    with open(path, "w") as f:
        f.write(text)
    os.chmod(path, os.stat(path).st_mode | stat.S_IXUSR)


def generate():
    with tempfile.TemporaryDirectory() as d:
        config = f"{d}/config"
        init = open(f"{PACKAGES}/wayland/compositor/sway/autostart/111-sway-init").read()
        start = init.index("# Move the secondary window to the second output")
        dual = init[start:init.index('if [ "${QUIRK_DEVICE}" = "AYN Thor Lite" ]', start)]
        script = ('QUIRK_DEVICE="AYN Thor"; DEVICE_HAS_DUAL_SCREEN=true; connected_cons=(DSI-2 DSI-1); con=DSI-2;\n'
                  f'SWAY_HOME="{d}"; env_file="{d}/env"\n' + dual)
        subprocess.run(["bash", "-c", script], check=True)
        rotate = rewrite(open(f"{HERE}/thor-sway-rotate.sh").read(),
                         {"/storage/.config/sway/config": config, "/storage/.config/system/configs/system.cfg": f"{d}/system.cfg",
                          "/sys/module/panel_chipone_icna35xx/parameters/ultra_black": f"{d}/ultra_black"})
        open(f"{d}/system.cfg", "w").close()
        subprocess.run(["sh", "-c", rotate], check=True)
        return open(config).read()


CRITERION = re.compile(r'(\w+)="((?:[^"\\]|\\.)*)"')


def rules(config):
    out = []
    for line in config.splitlines():
        m = re.match(r"(for_window|assign) \[(.*?)\] (.*)", line)
        if m and not (m.group(1) == "for_window" and m.group(3).startswith("seat")):
            crit = CRITERION.findall(m.group(2))
            assert crit, line
            out.append((m.group(1), crit, m.group(3)))
    return out


ALL = rules(generate())


def applied(title, app_id=None, cls=None):
    """Every command sway would run for this window, joined. A criterion on a property the window doesn't have doesn't match
    (sway: XWayland windows have a class and no app_id, Wayland ones the reverse)."""
    props = {"title": title, "app_id": app_id, "class": cls}
    out = []
    for kind, crit, cmd in ALL:
        if all(props.get(k) is not None and re.search(v, props[k]) for k, v in crit):
            out.append(f"{kind}: {cmd}")
    return "\n".join(out)


def to_bottom(cmds):
    return "assign: output DSI-1" in cmds or "move window to output DSI-1" in cmds


def powers_on(cmds):
    return "output DSI-1 power on" in cmds


# GAME-10: a game's main window is full screen and not sent to the bottom screen or powering it on.
for title, app in (("Metroid", "org.mgba.mGBA"), ("RetroArch mGBA", "retroarch"), ("melonDS", "net.kuribo64.melonDS")):
    cmds = applied(title, app)
    assert "fullscreen enable" in cmds and not to_bottom(cmds) and not powers_on(cmds), (title, cmds)

# COMP-1: each title word sends a second window to the bottom screen, powers it on, rotates it and enables its touch, and it doesn't
# take fullscreen from the game by the top screen's rule.
for title in ("Foo Secondary", "[w2] melonDS", "Sub", "Bottom Screen", "App Screen 2", "Wii U GamePad"):
    cmds = applied(title, "some.app")
    assert to_bottom(cmds), (title, cmds)
    assert powers_on(cmds), (title, cmds)
    assert "thor-bottom-rotate.sh" in cmds, (title, cmds)
    assert 'input "0:0:bottom_touchscreen" events enabled' in cmds, (title, cmds)
    assert "fullscreen enable" not in cmds, (title, cmds)
# melonDS's second window lands there from the start, so it can't steal fullscreen on the top screen.
assert "assign: output DSI-1" in applied("[w2] melonDS", "melonDS")
assert "assign: output DSI-1" not in applied("melonDS", "melonDS")

# COMP-2: Eden Duo's companion fills the bottom screen and gives focus back.
cmds = applied("Eden - Screen 2 (DSMod aux)", "eden-duo")
assert to_bottom(cmds) and powers_on(cmds) and "fullscreen enable, focus output DSI-2" in cmds, cmds

# COMP-3: lowerdeck goes to the bottom screen with focus kept on top, and the top screen's fullscreen rule leaves it alone.
cmds = applied("lowerdeck", "lowerdeck")
assert "assign: output DSI-1" in cmds and "focus output DSI-2" in cmds and "thor-bottom-rotate.sh" in cmds, cmds
assert "no_focus [app_id=\"lowerdeck\"]" in generate()

# COMP-4: the ports the user installs.
cmds = applied("GamePad — Vulkan", "zeldawwhd")                    # Wind Waker HD
assert to_bottom(cmds) and powers_on(cmds) and "fullscreen enable, focus output DSI-2" in cmds, cmds
cmds = applied("Dusklight — Second Screen", "dusklight")           # Dusklight
assert "assign: output DSI-1" in cmds and "fullscreen enable, output DSI-1 power on, focus output DSI-2" in cmds, cmds
assert "thor-bottom-rotate.sh 1.5" in cmds and 'events enabled' in cmds
cmds = applied("gen1recomp Secondary Display", cls="love.aarch64")   # Gen1 Recomp's secondary display, under XWayland
assert to_bottom(cmds) and powers_on(cmds), cmds
assert 'fullscreen enable, exec swaymsg \'[class="^love\\.aarch64$" title="^(?!.*Secondary)"] focus\'' in cmds, cmds
cmds = applied("gen1recomp", cls="love.aarch64")                     # and its main window stays on top
assert "assign: output DSI-2" in cmds and not to_bottom(cmds), cmds
cmds = applied("Mozilla Firefox", "lumidex")                         # Lumi-Dex, opened by Brilliant Diamond
assert "assign: output DSI-1" in cmds and "output DSI-1 power on, focus output DSI-2" in cmds and 'events enabled' in cmds, cmds
assert "/storage/.config/thor/lumi-dex.sh" in applied("Pokemon Brilliant Diamond", "eden")
assert "lumi-dex.sh" not in applied("Metroid", "eden")


def with_swaymsg(answer):
    """A fake swaymsg answering -t queries with `answer`; returns (dir, env)."""
    d = tempfile.TemporaryDirectory()
    executable(f"{d.name}/swaymsg", f'#!/bin/sh\ncase "$1" in -t) cat "{d.name}/answer" ;; *) echo "$*" >>"{d.name}/calls" ;; esac\n')
    with open(f"{d.name}/answer", "w") as f:
        f.write(answer)
    return d, {**os.environ, "PATH": f"{d.name}:" + os.environ["PATH"]}


def calls(d):
    return open(f"{d.name}/calls").read().splitlines() if os.path.exists(f"{d.name}/calls") else []


# GAME-10: with nothing on the bottom screen it goes off after the launch; with a window there it stays on. Home starts this.
TREE = '{"type":"root","nodes":[{"type":"output","name":"DSI-2","nodes":[{"pid":1}]},{"type":"output","name":"DSI-1","nodes":[%s]}]}'
for window, want in (("", ["output DSI-1 power off"]), ('{"pid":2}', [])):
    d, env = with_swaymsg(TREE % window)
    subprocess.run(["sh", f"{HERE}/thor-bottom-idle-off.sh", "0"], check=False, env=env)
    assert calls(d) == want, (window, calls(d))
    d.cleanup()
# A visible window on the top screen's workspace that reaches into the bottom panel keeps it on: RetroArch spanning both for a DS
# game (COMP-5), with DSI-1 placed below DSI-2. One that only touches its edge, or a hidden one, doesn't.
SPAN = ('{"type":"root","nodes":[{"type":"output","name":"__i3","rect":{"x":0,"y":0,"width":3160,"height":2160},"nodes":[%s]},'
        '{"type":"output","name":"DSI-2","rect":{"x":0,"y":0,"width":1920,"height":1080},"nodes":[{"type":"workspace",'
        '"floating_nodes":[%s]}]},{"type":"output","name":"DSI-1","rect":{"x":340,"y":1080,"width":1240,"height":1080},"nodes":[]}]}')
RA = '{"pid":3,"visible":%s,"rect":{"x":240,"y":0,"width":1440,"height":%d}}'
for scratch, window, want in (("", RA % ("true", 2160), []), ("", RA % ("true", 1080), ["output DSI-1 power off"]),
                              ("", RA % ("false", 2160), ["output DSI-1 power off"]), (RA % ("true", 2160), "", ["output DSI-1 power off"])):
    d, env = with_swaymsg(SPAN % (scratch, window))
    subprocess.run(["sh", f"{HERE}/thor-bottom-idle-off.sh", "0"], check=False, env=env)
    assert calls(d) == want, (scratch, window, calls(d))
    d.cleanup()
source = open(f"{PACKAGES}/asgard-home/src/backend.cpp").read()
run_body = source[source.index("void Backend::run("):source.index("// --- in-game menu")]
assert re.search(r'^\s*"swaymsg .*thor-bottom-idle-off\.sh 3', run_body, re.M), "Home no longer arms the bottom screen's off"

# COMP-1: the rotation only happens when the panel isn't already landscape: each one is a modeset.
for transform, want in (("270", ["output DSI-1 transform 90"]), ("90", [])):
    d, env = with_swaymsg('[{"name":"DSI-1","transform":"%s"}]' % transform)
    subprocess.run(["sh", f"{HERE}/thor-bottom-rotate.sh"], check=True, env=env)
    assert calls(d) == want, (transform, calls(d))
    d.cleanup()


# COMP-3: vertical-check starts lowerdeck for a RetroArch game unless the setting says off; unset means vc, and is saved.
# COMP-5: a DS core instead gets RetroArch's window across both screens, with the bottom panel placed below the top one.
# It reads runemu.sh's arguments from /proc: Asgard Home's launch shell comes first (lower pid) and holds `--core="$3"` in its
# script text, which `ps aux | grep runemu.sh` once read as the core, so no DS game got the span.
HOME_SHELL = ["/bin/bash", "-c", 'swaymsg focus; "$5" "$1" -P"$2" --core="$3" --emulator="$4" --controllers=""; rc=$?', "run"]


def vertical_check(setting, rom="/roms/gba/Metroid.gba", platform="gba", core="mgba"):
    with tempfile.TemporaryDirectory() as t:
        os.makedirs(f"{t}/lowerdeck")
        executable(f"{t}/swaymsg", f'#!/bin/sh\necho "$*" >>"{t}/sway"\nexit 1\n')
        executable(f"{t}/pgrep", "#!/bin/sh\nexit 1\n")
        executable(f"{t}/python3", f'#!/bin/sh\necho "$*" >>"{t}/started"\n')
        runemu = ["/usr/bin/runemu.sh", rom, f"-P{platform}", f"--core={core}", "--emulator=retroarch", "--controllers="]
        for pid, argv in ((100, HOME_SHELL + [rom, platform, core, "retroarch", "/usr/bin/runemu.sh"]),
                          (101, ["/bin/bash"] + runemu), (102, ["sleep", "1"])):
            os.makedirs(f"{t}/proc/{pid}")
            with open(f"{t}/proc/{pid}/cmdline", "wb") as f:
                f.write(b"".join(a.encode() + b"\0" for a in argv))
        with open(f"{t}/profile", "w") as f:
            f.write(f'''get_setting() {{ [ "$1" = asgardos.bottomscreen.type ] && cat "{t}/setting" 2>/dev/null; }}
set_setting() {{ echo "$1=$2" >>"{t}/set"; }}
export PATH="{t}:$PATH" DEVICE_HAS_DUAL_SCREEN=true QUIRK_DEVICE="AYN Thor"
''')
        if setting:
            with open(f"{t}/setting", "w") as f:
                f.write(setting)
        script = rewrite(open(f"{PACKAGES}/asgardos/sources/scripts/vertical-check").read(),
                         {". /etc/profile": f". {t}/profile", "/usr/share/lowerdeck": f"{t}/lowerdeck", "/run/lowerdeck.pid": f"{t}/pid",
                          "/sys/class/drm": f"{t}/drm", "/proc/": f"{t}/proc/"})
        subprocess.run(["bash", "-c", script], check=False, capture_output=True, timeout=30, env={**os.environ})
        for _ in range(20):      # it starts lowerdeck in the background
            if os.path.exists(f"{t}/started"):
                break
            subprocess.run(["sleep", "0.05"])
        started = open(f"{t}/started").read() if os.path.exists(f"{t}/started") else ""
        saved = open(f"{t}/set").read() if os.path.exists(f"{t}/set") else ""
        sway = open(f"{t}/sway").read() if os.path.exists(f"{t}/sway") else ""
        return started, saved, sway


def lowerdeck(setting):
    started, saved, _ = vertical_check(setting)
    assert not started or "--platform gba" in started and "--core mgba" in started, started
    return bool(started), saved


assert lowerdeck("vc") == (True, "")
assert lowerdeck("") == (True, "asgardos.bottomscreen.type=vc\n")
assert lowerdeck("off") == (False, "")
for core, width in (("melondsds", "1440"), ("melonds", "1240"), ("desmume", "1240")):
    started, _, sway = vertical_check("vc", "/roms/nds/Pokemon - Black Version (USA, Europe).nds", "nds", core)
    assert not started, (core, started)
    assert "output DSI-1 power on pos 340 1080" in sway, (core, sway)
    assert f"floating enable, fullscreen disable, resize set {width} 2160, move to output DSI-2" in sway, (core, sway)
print("ok")
